    pub fn new(cfg: BlackboardConfig, vb: VarBuilder) -> Result<Self> {
        let in_proj = candle_nn::linear(cfg.latent_dim, cfg.hidden_dim, vb.pp("in_proj"))?;
        let upd_proj = candle_nn::linear(cfg.hidden_dim, cfg.hidden_dim, vb.pp("upd_proj"))?;
        let readout = candle_nn::linear(cfg.hidden_dim, cfg.latent_dim, vb.pp("readout"))?;
        Ok(Self {
            cfg,
            in_proj,
            upd_proj,
            readout,
            perm_cache: OnceCell::new(),
            inv_perm_cache: OnceCell::new(),
        })
    }

